#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long k;
    cin >> k;
    string s;
    cin >> s;

    int shift = k % 26;
    string result = "";
    for (char ch : s) {
        int position = (ch - 'a' + shift) % 26;
        result += (char) ('a' + position);
    }
    cout << result << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long k = sc.nextLong();
        String s = sc.next();

        int shift = (int) (k % 26);
        String result = "";
        for (int i = 0; i < s.length(); i++) {
            int position = (s.charAt(i) - 'a' + shift) % 26;
            result += (char) ('a' + position);
        }
        System.out.println(result);
    }
}
